package com.nextfeet.nextfeet.repository; import java.util.*; import org.springframework.jdbc.core.*; import org.springframework.stereotype.Repository; import com.nextfeet.nextfeet.model.Categoria; @Repository public class CategoriaRepository implements CategoriaDAO {private final JdbcTemplate db; public CategoriaRepository(JdbcTemplate db){this.db=db;} private final RowMapper<Categoria> map=(r,n)->new Categoria(r.getInt("id"),r.getString("nombre"),r.getString("descripcion"),r.getString("estado")); public List<Categoria> listar(){return db.query("select * from categoria order by id desc",map);} public Categoria obtener(Integer id){return db.query("select * from categoria where id=?",map,id).stream().findFirst().orElse(null);} public void crear(Categoria c){db.update("insert into categoria(nombre,descripcion,estado) values(?,?,?)",c.getNombre(),c.getDescripcion(),"ACTIVO");} public void actualizar(Categoria c){db.update("update categoria set nombre=?,descripcion=? where id=?",c.getNombre(),c.getDescripcion(),c.getId());} public void desactivar(Integer id){db.update("update categoria set estado='INACTIVO' where id=?",id);} }